param([ValidateSet('Chrome','Edge')][string]$Browser='Chrome');$url='http://127.0.0.1:3000/kiosk';$exe=if($Browser -eq 'Edge'){'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'}else{'C:\Program Files\Google\Chrome\Application\chrome.exe'}
while($true){try{Invoke-WebRequest 'http://127.0.0.1:3000/api/health' -UseBasicParsing -TimeoutSec 5|Out-Null;if(-not(Get-CimInstance Win32_Process|?{$_.Name -match 'chrome|msedge' -and $_.CommandLine -like "*$url*"})){Start-Process $exe "--kiosk --app=$url --no-first-run --disable-session-crashed-bubble"}}catch{};Start-Sleep 10}
